import Foundation

/// Published reference data shipped with the app; no network access at runtime.
///
/// The list is generated by Tools/sync_targets.py from the drop folder of
/// target curve files and written to the bundle's Targets/manifest.json, so
/// adding a target is dropping a file in that folder and rebuilding.
public struct BuiltInTarget: Hashable, Identifiable, Sendable {
    public let id: String
    public let name: String

    public init(id: String, name: String) {
        self.id = id
        self.name = name
    }

    /// The manifest entry's id; kept so pickers keyed by string still work.
    public var rawValue: String { id }

    /// All bundled targets, in manifest order. The manifest is part of the
    /// app bundle, so this is as static as the compiled-in list it replaced;
    /// the working-directory fallback covers the offline test runner, whose
    /// executable lives outside any app bundle, and an empty list means the
    /// manifest was missing from both.
    public static let all: [BuiltInTarget] = {
        let directories = [bundledDirectory(),
                           URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
                               .appendingPathComponent("Resources/Targets")]
        for directory in directories {
            guard let directory,
                  let data = try? Data(contentsOf: directory.appendingPathComponent("manifest.json")),
                  let decoded = try? JSONDecoder().decode([Entry].self, from: data) else { continue }
            return decoded.map { BuiltInTarget(id: $0.id, name: $0.name) }
        }
        return []
    }()

    public static func withID(_ id: String) -> BuiltInTarget? {
        all.first { $0.id == id }
    }

    private struct Entry: Decodable {
        let id: String
        let name: String
        let file: String
    }

    public func load(from directory: URL) throws -> FrequencyResponse {
        let path = directory.appendingPathComponent(rawValue + ".csv")
        let text = try String(contentsOf: path, encoding: .utf8)
        guard let response = FrequencyResponse.parse(text, name: name),
              response.points.count >= 8, response.range.low <= 200, response.range.high >= 2000 else {
            throw CocoaError(.fileReadCorruptFile)
        }
        return response
    }
    public static func bundledDirectory(in bundle: Bundle = .main) -> URL? {
        bundle.resourceURL?.appendingPathComponent("Targets", isDirectory: true)
    }
}
